import { useEffect, useState } from 'react'

function AccountPage() {
  const [user, setUser] = useState(null)

  useEffect(() => {
    const saved = localStorage.getItem('user')
    if (saved) setUser(JSON.parse(saved))
  }, [])

  if (!user) {
    return (
      <div style={{ padding:20 }}>
        <h2>No account found</h2>
        <p>You need login so information shows here.</p>
      </div>
    )
  }

  return (
    <div className="account-container">
      <aside className="sidebar">
        <div className="profile">
          <img src={user.image ? user.image : "/avatar.png"} className="avatar"/>
          <p className="name">{user.name}</p>
          <p className="email">{user.email}</p>
        </div>

        <div className="menu">
          <p>Overview</p>
          <p>Orders</p>
          <p>Address</p>
          <p>Logout</p>
        </div>
      </aside>

      <main className="content">
        <h2>Account Details</h2>
        <div className="box">
          <p>Name: {user.name}</p>
          <p>Email: {user.email}</p>
          <p>Phone: {user.phone ? user.phone : "No phone added"}</p>
          <p>Address: {user.address ? user.address : "No address added"}</p>
        </div>
      </main>
    </div>
  )
}

export default AccountPage
